import random
import string
import logging
from datetime import datetime

# Synthetic data generator (no real personal information)
class SyntheticData:
    @staticmethod
    def generate_user_record():
        return {
            "user_id": random.randint(1000, 9999),
            "name": ''.join(random.choices(string.ascii_lowercase, k=8)),
            "email": f"{''.join(random.choices(string.ascii_lowercase, k=5))}@example.com",
            "ssn_last4": f"{random.randint(1000, 9999)}",  # not real
            "balance": round(random.uniform(100, 10000), 2)
        }

# Simulation of a vulnerable database endpoint (e.g., SQL injection or unprotected API)
class VulnerableServer:
    def __init__(self):
        self.database = [SyntheticData.generate_user_record() for _ in range(100)]
        self.access_log = []

    def query(self, sql_input):
        # Simulated insecure query – logs every request
        self.access_log.append({
            "timestamp": datetime.now(),
            "input": sql_input,
            "result_count": len(self.database) if "SELECT *" in sql_input else 0
        })
        # In a real simulation, you'd parse SQL attempts
        return self.database if "1=1" in sql_input else []

# Attacker simulator (controlled by you, running in isolated VM)
class EthicalAttacker:
    def __init__(self, server):
        self.server = server

    def attempt_extraction(self, technique="sql_injection"):
        if technique == "sql_injection":
            payload = "SELECT * FROM users WHERE 1=1"
        elif technique == "api_abuse":
            payload = "GET /api/users?limit=1000"
        else:
            payload = "unknown"
        result = self.server.query(payload)
        logging.info(f"Attack attempt: {technique} -> retrieved {len(result)} records")
        return result

# Defensive monitoring system (show how to detect anomalies)
class IntrusionDetector:
    def __init__(self, server):
        self.server = server

    def analyze_logs(self):
        large_requests = [entry for entry in self.server.access_log 
